/**
 * Attaches listeners to the router navigation events, returning a cleanup
 * function that removes them.
 */
export function initListeners(): () => void {
  const expoGlobal = (globalThis as any)?.expo;
  if (!expoGlobal || !('router' in expoGlobal)) {
    return () => {};
  }

  const router = expoGlobal.router as RouterGlobal | undefined;
  const navigationEvents = router?.navigationEvents;
  if (!navigationEvents) {
    return () => {};
  }

  navigationEvents.enable?.();
  navigationEvents.saveCurrentPathname?.();
  const remove = navigationEvents.addListener?.('pageFocused', () => {});

  return () => {
    if (typeof remove === 'function') {
      remove();
    }
  };
